insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('kegel-basico', 'Kegel básico', 'assoalho', 1, 4, 'Aprender a contrair e relaxar o músculo pubococcígeo (PC), o principal músculo envolvido no reflexo da ejaculação.', 'Estudos de reabilitação do assoalho pélvico mostram que homens que treinam esses músculos por 8 a 12 semanas ganham tempo e controle. Um músculo forte e consciente permite segurar o reflexo quando a excitação sobe.', '["Encontre o músculo: é o mesmo que você usa para segurar o xixi no meio do caminho ou para segurar um gás. Use esse teste só para identificar, não treine urinando.","Deite de costas com os joelhos dobrados e os pés apoiados no chão.","Contraia o músculo PC como se puxasse a base do pênis para dentro e para cima.","Segure a contração pelo tempo indicado no cronômetro.","Solte totalmente e relaxe pelo mesmo tempo. O relaxamento é tão importante quanto a contração."]'::jsonb, '["Não prenda a respiração: respire normalmente durante toda a contração.","Glúteos, coxas e barriga devem ficar soltos.","Se o pênis se mexer levemente para cima, você está contraindo o músculo certo."]'::jsonb, '["Apertar os glúteos ou a barriga no lugar do assoalho pélvico.","Treinar enquanto urina (pode atrapalhar o esvaziamento da bexiga).","Fazer centenas de repetições por dia: excesso causa fadiga e tensão."]'::jsonb, '/images/exercicios/kegel-basico.webp', null, '{"tipo":"intervalo","contrair":3,"relaxar":3,"reps":10,"series":3,"descanso":30}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('kegel-sustentado', 'Kegel sustentado', 'assoalho', 2, 6, 'Aumentar a resistência do músculo PC segurando contrações longas.', 'No momento da relação você precisa de um músculo que aguente vários segundos de controle, não só um aperto rápido.', '["Sentado ou deitado, faça uma contração do PC com cerca de 70% da sua força.","Mantenha a contração estável pelo tempo do cronômetro, respirando devagar.","Solte completamente e descanse pelo tempo indicado.","Repita até completar as repetições."]'::jsonb, '["Se a contração ''escapar'' antes do tempo, diminua para 5 segundos e vá subindo.","Imagine um elevador subindo e parando no terceiro andar."]'::jsonb, '["Usar 100% da força e perder a contração logo.","Esquecer o relaxamento entre as repetições."]'::jsonb, '/images/exercicios/kegel-sustentado.webp', null, '{"tipo":"intervalo","contrair":10,"relaxar":10,"reps":8,"series":2,"descanso":45}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('kegel-rapido', 'Kegel rápido (flicks)', 'assoalho', 2, 3, 'Treinar contrações rápidas e fortes para frear o reflexo na hora certa.', 'Quando você sente o ponto de não retorno chegando, uma contração rápida e firme ajuda a segurar a onda.', '["Contraia o PC o mais forte e rápido que conseguir.","Solte imediatamente.","Repita no ritmo do cronômetro, sem pausas longas."]'::jsonb, '["Qualidade acima de velocidade: cada contração precisa ser completa.","Solte de verdade entre um aperto e outro."]'::jsonb, '["Fazer contrações pela metade.","Prender a respiração."]'::jsonb, '/images/exercicios/kegel-rapido.webp', null, '{"tipo":"intervalo","contrair":1,"relaxar":1,"reps":20,"series":3,"descanso":30}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('kegel-elevador', 'Kegel elevador', 'assoalho', 3, 5, 'Controlar a força da contração em níveis, como os andares de um elevador.', 'Controle fino é o que permite ajustar a excitação sem parar tudo. Você aprende a dosar o músculo.', '["Contraia levemente (1º andar) e segure 2 segundos.","Aumente um pouco (2º andar) e segure 2 segundos.","Aumente até o máximo (3º andar) e segure 2 segundos.","Desça andar por andar até relaxar totalmente."]'::jsonb, '["Faça devagar. É um exercício de percepção, não de força."]'::jsonb, '["Pular direto do 1º para o 3º andar."]'::jsonb, '/images/exercicios/kegel-elevador.webp', null, '{"tipo":"intervalo","contrair":6,"relaxar":6,"reps":6,"series":2,"descanso":45}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('kegel-reverso', 'Kegel reverso (relaxamento)', 'assoalho', 1, 4, 'Aprender a soltar e alongar o assoalho pélvico de forma consciente.', 'Muitos homens com ejaculação precoce têm o assoalho pélvico tenso o tempo todo. Saber relaxar esse músculo durante a relação reduz a pressão que dispara o reflexo.', '["Deite de costas, joelhos dobrados, mãos na barriga.","Inspire pelo nariz, deixando a barriga subir.","Ao soltar o ar, empurre suavemente o assoalho pélvico para baixo e para fora, como se começasse a urinar devagar.","Mantenha essa sensação de abertura por alguns segundos e volte ao neutro."]'::jsonb, '["É um empurrão leve. Não faça força como se estivesse no banheiro.","Combine com a respiração diafragmática."]'::jsonb, '["Fazer força excessiva.","Contrair a barriga no lugar de soltar."]'::jsonb, '/images/exercicios/kegel-reverso.webp', null, '{"tipo":"intervalo","contrair":5,"relaxar":5,"reps":10,"series":2,"descanso":30,"rotulos":["Soltar","Neutro"]}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('respiracao-diafragmatica', 'Respiração diafragmática', 'respiracao', 1, 5, 'Baixar a ansiedade e o ritmo do coração usando a respiração pela barriga.', 'Ansiedade acelera a ejaculação. Respirar fundo e devagar ativa o sistema nervoso parassimpático, que acalma o corpo e afasta o ponto de não retorno.', '["Sente ou deite confortável. Uma mão no peito e outra na barriga.","Inspire pelo nariz enchendo a barriga. A mão do peito quase não se mexe.","Segure um instante.","Solte o ar pela boca, devagar, esvaziando a barriga."]'::jsonb, '["Use essa respiração durante a relação quando sentir a excitação subindo rápido."]'::jsonb, '["Respirar só com o peito.","Puxar o ar com força."]'::jsonb, '/images/exercicios/respiracao-diafragmatica.webp', null, '{"tipo":"respiracao","inspirar":4,"segurar":2,"expirar":6,"segurar2":0,"ciclos":10}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('respiracao-4-7-8', 'Respiração 4-7-8', 'respiracao', 2, 3, 'Acalmar rapidamente antes de um encontro ou para dormir melhor.', 'A expiração longa desacelera o coração e reduz a ansiedade de desempenho.', '["Inspire pelo nariz contando 4.","Segure o ar contando 7.","Solte pela boca contando 8, fazendo um leve som de sopro."]'::jsonb, '["Comece com 4 ciclos. Se sentir tontura, pare e respire normal."]'::jsonb, '["Fazer rápido demais."]'::jsonb, '/images/exercicios/respiracao-478.webp', null, '{"tipo":"respiracao","inspirar":4,"segurar":7,"expirar":8,"segurar2":0,"ciclos":6}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('respiracao-quadrada', 'Respiração quadrada', 'respiracao', 1, 4, 'Manter o foco e o ritmo calmo, técnica usada por atletas e militares.', 'Ritmo constante tira a mente da ansiedade e ajuda a manter a excitação em nível moderado.', '["Inspire contando 4.","Segure contando 4.","Expire contando 4.","Segure vazio contando 4."]'::jsonb, '["Ótima para usar no meio da relação, num ritmo mais curto (3-3-3-3)."]'::jsonb, '["Tensionar os ombros."]'::jsonb, '/images/exercicios/respiracao-quadrada.webp', null, '{"tipo":"respiracao","inspirar":4,"segurar":4,"expirar":4,"segurar2":4,"ciclos":8}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('escala-excitacao', 'Escala de excitação (0 a 10)', 'tecnica', 1, 10, 'Aprender a perceber em que nível de excitação você está a cada momento.', 'Quem ejacula rápido geralmente não percebe a subida até ser tarde demais. Dar nota à excitação é a base de todas as outras técnicas.', '["Durante a masturbação, sozinho e sem pressa, dê notas de 0 a 10 para sua excitação.","0 é nada, 5 é excitação confortável, 8 é bem perto, 9,5 é o ponto de não retorno, 10 é a ejaculação.","Tente ficar entre 5 e 7 pelo maior tempo possível.","Anote no app quanto tempo conseguiu ficar na zona de controle."]'::jsonb, '["Sem pornografia: ela acelera a excitação e atrapalha a percepção.","Use lubrificante para deixar a sensação mais parecida com a relação."]'::jsonb, '["Ir direto para o fim.","Ficar com medo de chegar perto do 8. É ali que o treino acontece."]'::jsonb, '/images/exercicios/escala-excitacao.webp', null, '{"tipo":"tempo","segundos":600,"series":1}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('para-e-recomeca', 'Para e recomeça (start-stop)', 'tecnica', 2, 15, 'Treinar o corpo a aguentar níveis altos de excitação sem ejacular.', 'Técnica descrita pelo urologista James Semans em 1956 e ainda recomendada por sociedades de urologia. Ensina o reflexo a esperar.', '["Comece a estimulação sozinho (ou com parceria) sem pressa.","Quando chegar ao nível 7 ou 8, pare totalmente a estimulação.","Respire fundo pela barriga e espere a excitação cair para 4 ou 5 (de 30 a 60 segundos).","Recomece. Repita o ciclo 3 vezes antes de permitir a ejaculação na 4ª vez.","Registre quantos ciclos conseguiu."]'::jsonb, '["Faça de 3 a 4 vezes por semana.","Depois de dominar sozinho, pratique com sua parceria."]'::jsonb, '["Parar tarde demais (no 9).","Se culpar quando ''escapar''. Faz parte do aprendizado."]'::jsonb, '/images/exercicios/para-e-recomeca.webp', null, '{"tipo":"ciclos","ciclos":4,"pausa":45}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('aperto', 'Técnica do aperto (squeeze)', 'tecnica', 2, 15, 'Reduzir a excitação rapidamente com uma pressão na glande.', 'Desenvolvida por Masters e Johnson, interrompe o reflexo e dá tempo para retomar o controle.', '["Quando chegar ao nível 7 ou 8, pare a estimulação.","Segure o pênis com o polegar embaixo, logo abaixo da glande, e o indicador e o médio em cima.","Aperte com firmeza (sem dor) por 10 a 20 segundos, até a vontade de ejacular passar.","Espere 30 segundos e recomece. Repita 3 a 4 vezes."]'::jsonb, '["A ereção pode diminuir um pouco. Isso é normal e ela volta.","Pode ser feita pela parceria."]'::jsonb, '["Apertar forte demais e causar dor.","Apertar já no ponto de não retorno: aí é tarde."]'::jsonb, '/images/exercicios/aperto.webp', null, '{"tipo":"ciclos","ciclos":4,"pausa":20}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('foco-sensorial', 'Foco sensorial (a dois)', 'tecnica', 3, 20, 'Diminuir a ansiedade de desempenho e reconectar com a parceria.', 'Usado por terapeutas sexuais. Tira o foco da penetração e da ''performance'', o que reduz a ansiedade, um dos principais gatilhos da ejaculação precoce.', '["Combinem: nesta sessão não haverá penetração.","Revezem toques pelo corpo um do outro por 10 minutos cada, sem tocar áreas genitais na primeira semana.","Prestem atenção na textura, na temperatura e na respiração.","Na segunda semana, incluam toques genitais, ainda sem penetração.","Conversem depois: o que foi bom, o que foi diferente."]'::jsonb, '["Comunicação é metade do tratamento.","Combine com a respiração diafragmática."]'::jsonb, '["Pular etapas.","Transformar em teste de desempenho."]'::jsonb, '/images/exercicios/foco-sensorial.webp', null, '{"tipo":"tempo","segundos":1200,"series":1}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('ponte-gluteo', 'Ponte de glúteo', 'corpo', 1, 4, 'Fortalecer glúteos e assoalho pélvico juntos.', 'A ponte trabalha a musculatura que sustenta a pelve. Somando um Kegel no topo, você treina o PC em posição funcional.', '["Deite de costas, joelhos dobrados, pés na largura do quadril.","Suba o quadril até formar uma linha reta dos ombros aos joelhos.","No topo, faça um Kegel e segure 3 segundos.","Desça devagar."]'::jsonb, '["Empurre o chão com os calcanhares.","Não arqueie a lombar."]'::jsonb, '["Subir alto demais e forçar a coluna."]'::jsonb, null, '["/exercicios/Butt_Lift_Bridge/0.jpg","/exercicios/Butt_Lift_Bridge/1.jpg"]'::jsonb, '{"tipo":"reps","reps":12,"series":3,"descanso":40}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('ponte-unilateral', 'Ponte com uma perna', 'corpo', 2, 5, 'Aumentar a estabilidade da pelve e a força dos glúteos.', 'Exige mais controle do assoalho pélvico para manter o quadril reto.', '["Deite com os joelhos dobrados e estenda uma perna.","Suba o quadril apoiado só em um pé.","Segure 2 segundos no topo e desça.","Troque de lado."]'::jsonb, '["Mantenha o quadril nivelado, sem cair para um lado."]'::jsonb, '["Girar o quadril."]'::jsonb, null, '["/exercicios/Single_Leg_Glute_Bridge/0.jpg","/exercicios/Single_Leg_Glute_Bridge/1.jpg"]'::jsonb, '{"tipo":"reps","reps":10,"series":2,"descanso":40}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('inclinacao-pelvica', 'Inclinação pélvica para ponte', 'corpo', 1, 4, 'Ganhar mobilidade e consciência da pelve.', 'Ensina a mover a pelve com controle, útil para ajustar ritmo e profundidade durante a relação.', '["Deite de costas, joelhos dobrados.","Encaixe o quadril, colando a lombar no chão.","Suba vértebra por vértebra até a ponte.","Desça vértebra por vértebra."]'::jsonb, '["Movimento lento e fluido."]'::jsonb, '["Subir de uma vez só."]'::jsonb, null, '["/exercicios/Pelvic_Tilt_Into_Bridge/0.jpg","/exercicios/Pelvic_Tilt_Into_Bridge/1.jpg"]'::jsonb, '{"tipo":"reps","reps":10,"series":2,"descanso":30}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('agachamento', 'Agachamento livre', 'corpo', 1, 5, 'Fortalecer pernas, glúteos e melhorar a circulação na região pélvica.', 'Exercício de força melhora a circulação, a testosterona e a resistência física.', '["Pés na largura dos ombros.","Desça como se fosse sentar em uma cadeira.","Desça até as coxas ficarem paralelas ao chão.","Suba empurrando o chão."]'::jsonb, '["Joelhos na direção da ponta dos pés.","Peito aberto."]'::jsonb, '["Tirar os calcanhares do chão.","Joelhos para dentro."]'::jsonb, null, '["/exercicios/Bodyweight_Squat/0.jpg","/exercicios/Bodyweight_Squat/1.jpg"]'::jsonb, '{"tipo":"reps","reps":15,"series":3,"descanso":45}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('agachamento-profundo', 'Agachamento profundo sustentado', 'alongamento', 2, 3, 'Alongar e relaxar o assoalho pélvico.', 'Na posição de cócoras o assoalho pélvico se alonga naturalmente. Ótimo para combinar com o Kegel reverso.', '["Abra os pés um pouco além da largura dos ombros.","Desça até a posição de cócoras.","Respire fundo pela barriga, soltando o assoalho a cada expiração."]'::jsonb, '["Se precisar, segure em algo firme à frente."]'::jsonb, '["Prender a respiração."]'::jsonb, null, '["/exercicios/Sit_Squats/0.jpg","/exercicios/Sit_Squats/1.jpg"]'::jsonb, '{"tipo":"tempo","segundos":45,"series":3,"descanso":20}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('afundo', 'Afundo (avanço) parado', 'corpo', 2, 5, 'Força de pernas e estabilidade do quadril.', 'Fortalece a cadeia que dá sustentação à pelve e melhora a resistência física na relação.', '["Um pé à frente e outro atrás.","Desça até os dois joelhos formarem 90 graus.","Suba e repita. Troque de perna."]'::jsonb, '["Tronco reto."]'::jsonb, '["Joelho da frente passar muito da ponta do pé."]'::jsonb, null, '["/exercicios/Split_Squats/0.jpg","/exercicios/Split_Squats/1.jpg"]'::jsonb, '{"tipo":"reps","reps":10,"series":2,"descanso":40}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('prancha', 'Prancha', 'corpo', 1, 3, 'Fortalecer o core, que trabalha junto com o assoalho pélvico.', 'Core forte melhora a postura, o controle do quadril e a resistência.', '["Apoie antebraços e pontas dos pés.","Corpo em linha reta da cabeça aos calcanhares.","Respire normalmente e segure."]'::jsonb, '["Contraia levemente o abdômen e o assoalho pélvico."]'::jsonb, '["Quadril muito alto ou caindo."]'::jsonb, null, '["/exercicios/Plank/0.jpg","/exercicios/Plank/1.jpg"]'::jsonb, '{"tipo":"tempo","segundos":30,"series":3,"descanso":30}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('prancha-lateral', 'Prancha lateral', 'corpo', 2, 3, 'Fortalecer os oblíquos e a estabilidade lateral do quadril.', 'Complementa a prancha e equilibra a musculatura que segura a pelve.', '["Deite de lado apoiado no antebraço.","Suba o quadril formando uma linha reta.","Segure e troque de lado."]'::jsonb, '["Cotovelo embaixo do ombro."]'::jsonb, '["Deixar o quadril cair."]'::jsonb, null, '["/exercicios/Side_Bridge/0.jpg","/exercicios/Side_Bridge/1.jpg"]'::jsonb, '{"tipo":"tempo","segundos":25,"series":2,"descanso":20}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('dead-bug', 'Dead bug', 'corpo', 2, 4, 'Coordenar respiração, abdômen profundo e assoalho pélvico.', 'Treina o controle do core sem pressionar a região pélvica.', '["Deite de costas, braços para o teto e joelhos a 90 graus.","Estenda braço direito e perna esquerda ao mesmo tempo, sem tirar a lombar do chão.","Volte e troque o lado."]'::jsonb, '["Expire ao estender."]'::jsonb, '["Arquear a lombar."]'::jsonb, null, '["/exercicios/Dead_Bug/0.jpg","/exercicios/Dead_Bug/1.jpg"]'::jsonb, '{"tipo":"reps","reps":12,"series":2,"descanso":30}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('abdominal-reverso', 'Abdominal reverso', 'corpo', 2, 3, 'Fortalecer a parte baixa do abdômen.', 'Abdômen inferior forte ajuda o controle da pelve.', '["Deite de costas com as pernas dobradas no ar.","Leve os joelhos em direção ao peito, tirando levemente o quadril do chão.","Desça devagar."]'::jsonb, '["Movimento curto e controlado."]'::jsonb, '["Usar impulso."]'::jsonb, null, '["/exercicios/Reverse_Crunch/0.jpg","/exercicios/Reverse_Crunch/1.jpg"]'::jsonb, '{"tipo":"reps","reps":12,"series":2,"descanso":30}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('superman', 'Superman', 'corpo', 1, 3, 'Fortalecer lombar e glúteos.', 'Equilibra o trabalho do abdômen e protege a coluna.', '["Deite de bruços com os braços à frente.","Erga braços, peito e pernas ao mesmo tempo.","Segure 2 segundos e desça."]'::jsonb, '["Olhe para o chão para não forçar o pescoço."]'::jsonb, '["Subir com tranco."]'::jsonb, null, '["/exercicios/Superman/0.jpg","/exercicios/Superman/1.jpg"]'::jsonb, '{"tipo":"reps","reps":12,"series":2,"descanso":30}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('coice-gluteo', 'Coice de glúteo (quatro apoios)', 'corpo', 1, 4, 'Ativar glúteos com a coluna protegida.', 'Glúteos fortes dão estabilidade à pelve e potência ao quadril.', '["Fique em quatro apoios.","Leve uma perna dobrada para trás e para cima.","Volte devagar. Troque de lado."]'::jsonb, '["Não gire o quadril."]'::jsonb, '["Arquear a lombar."]'::jsonb, null, '["/exercicios/Glute_Kickback/0.jpg","/exercicios/Glute_Kickback/1.jpg"]'::jsonb, '{"tipo":"reps","reps":12,"series":2,"descanso":30}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('escalador', 'Escalador (mountain climber)', 'corpo', 2, 3, 'Cardio e resistência sem equipamento.', 'Condicionamento cardiovascular melhora a circulação e a disposição.', '["Posição de flexão com braços estendidos.","Leve um joelho ao peito e troque rápido.","Mantenha o ritmo pelo tempo indicado."]'::jsonb, '["Quadril baixo."]'::jsonb, '["Quadril muito alto."]'::jsonb, null, '["/exercicios/Mountain_Climbers/0.jpg","/exercicios/Mountain_Climbers/1.jpg"]'::jsonb, '{"tipo":"tempo","segundos":30,"series":3,"descanso":30}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('pular-corda', 'Pular corda', 'corpo', 2, 6, 'Cardio intenso e rápido.', 'Aeróbico regular está associado a mais tempo de relação em estudos com homens sedentários.', '["Pule com os pés juntos, saltos baixos.","Gire a corda com os punhos, não com os braços.","Mantenha o ritmo pelo tempo indicado."]'::jsonb, '["Sem corda? Simule o movimento."]'::jsonb, '["Saltos altos demais."]'::jsonb, null, '["/exercicios/Rope_Jumping/0.jpg","/exercicios/Rope_Jumping/1.jpg"]'::jsonb, '{"tipo":"tempo","segundos":60,"series":4,"descanso":30}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('caminhada', 'Caminhada rápida ou corrida leve', 'corpo', 1, 30, 'Base aeróbica para saúde do coração e circulação.', 'Um estudo publicado no Turkish Journal of Urology (2017) encontrou mais tempo até a ejaculação em homens que corriam 30 minutos, 5 vezes por semana.', '["Caminhe em ritmo em que dê para falar, mas não cantar.","Mantenha por 30 minutos.","Faça de 3 a 5 vezes por semana."]'::jsonb, '["Ótimo para fazer junto com a respiração diafragmática."]'::jsonb, '["Começar intenso demais e desistir."]'::jsonb, null, '["/exercicios/Trail_Running_Walking/0.jpg","/exercicios/Trail_Running_Walking/1.jpg"]'::jsonb, '{"tipo":"tempo","segundos":1800,"series":1}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('gato-vaca', 'Gato e vaca', 'alongamento', 1, 3, 'Mobilizar coluna e pelve.', 'Solta a tensão da lombar e da pelve, onde muitos homens ansiosos acumulam rigidez.', '["Fique em quatro apoios.","Inspire arqueando as costas para baixo e olhando para frente.","Expire arredondando as costas, olhando para o umbigo."]'::jsonb, '["Sincronize com a respiração."]'::jsonb, '["Movimentos bruscos."]'::jsonb, null, '["/exercicios/Cat_Stretch/0.jpg","/exercicios/Cat_Stretch/1.jpg"]'::jsonb, '{"tipo":"reps","reps":10,"series":1}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('postura-crianca', 'Postura da criança', 'alongamento', 1, 2, 'Relaxar a lombar e o assoalho pélvico.', 'Posição de descanso que favorece o relaxamento do assoalho pélvico.', '["Ajoelhe e sente sobre os calcanhares.","Leve o tronco à frente com os braços estendidos.","Respire fundo pela barriga, sentindo as costas se expandirem."]'::jsonb, '["Abra os joelhos se for mais confortável."]'::jsonb, '["Prender a respiração."]'::jsonb, null, '["/exercicios/Childs_Pose/0.jpg","/exercicios/Childs_Pose/1.jpg"]'::jsonb, '{"tipo":"tempo","segundos":60,"series":2,"descanso":10}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('flexor-quadril', 'Alongamento do flexor do quadril', 'alongamento', 1, 3, 'Alongar a frente do quadril, que encurta com muito tempo sentado.', 'Flexores encurtados puxam a pelve e aumentam a tensão na região.', '["Ajoelhe com uma perna à frente.","Leve o quadril para frente até sentir alongar a frente da coxa de trás.","Segure e troque de lado."]'::jsonb, '["Encaixe o glúteo da perna de trás."]'::jsonb, '["Arquear a lombar."]'::jsonb, null, '["/exercicios/Kneeling_Hip_Flexor/0.jpg","/exercicios/Kneeling_Hip_Flexor/1.jpg"]'::jsonb, '{"tipo":"tempo","segundos":30,"series":2,"descanso":10}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('alongamento-gluteo', 'Alongamento de glúteo deitado', 'alongamento', 1, 3, 'Soltar glúteos e piriforme.', 'Músculos do quadril tensos se ligam ao assoalho pélvico. Soltá-los ajuda a relaxar a região.', '["Deite de costas.","Cruze um tornozelo sobre o joelho oposto.","Puxe a coxa de baixo em direção ao peito. Segure e troque."]'::jsonb, '["Respire fundo e solte a cada expiração."]'::jsonb, '["Forçar até doer."]'::jsonb, null, '["/exercicios/Lying_Glute/0.jpg","/exercicios/Lying_Glute/1.jpg"]'::jsonb, '{"tipo":"tempo","segundos":30,"series":2,"descanso":10}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into exercicios (id, nome, categoria, nivel, duracao_min, objetivo, por_que_ajuda, passos, dicas, erros, imagem, frames, timer) values ('alongamento-gluteo-sentado', 'Alongamento de glúteo sentado', 'alongamento', 1, 2, 'Versão para fazer no trabalho ou na cadeira.', 'Quebra a tensão de quem passa muitas horas sentado.', '["Sentado, cruze um tornozelo sobre o joelho oposto.","Incline o tronco à frente com a coluna reta.","Segure e troque de lado."]'::jsonb, '["Bom para fazer a cada 2 horas sentado."]'::jsonb, '["Curvar as costas."]'::jsonb, null, '["/exercicios/Seated_Glute/0.jpg","/exercicios/Seated_Glute/1.jpg"]'::jsonb, '{"tipo":"tempo","segundos":30,"series":2,"descanso":10}'::jsonb) on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria, nivel = excluded.nivel, duracao_min = excluded.duracao_min, objetivo = excluded.objetivo, por_que_ajuda = excluded.por_que_ajuda, passos = excluded.passos, dicas = excluded.dicas, erros = excluded.erros, imagem = excluded.imagem, frames = excluded.frames, timer = excluded.timer;
insert into nutrientes (id, nome, papel, meta, fontes) values ('zinco', 'Zinco', 'Participa da produção de testosterona e da saúde da próstata. Deficiência de zinco está ligada a baixa libido e problemas sexuais.', '11 mg por dia para homens adultos', '["Ostras","Carne vermelha magra","Semente de abóbora","Frango","Grão-de-bico","Castanha de caju"]'::jsonb) on conflict (id) do update set nome = excluded.nome, papel = excluded.papel, meta = excluded.meta, fontes = excluded.fontes;
insert into nutrientes (id, nome, papel, meta, fontes) values ('magnesio', 'Magnésio', 'Relaxa músculos e nervos, ajuda no sono e na regulação do estresse. Alguns estudos encontraram magnésio mais baixo em homens com ejaculação precoce.', '400 a 420 mg por dia', '["Folhas verde-escuras","Banana","Abacate","Amêndoas","Chocolate 70%","Feijão"]'::jsonb) on conflict (id) do update set nome = excluded.nome, papel = excluded.papel, meta = excluded.meta, fontes = excluded.fontes;
insert into nutrientes (id, nome, papel, meta, fontes) values ('vitamina-d', 'Vitamina D', 'Estudos associam níveis baixos de vitamina D à ejaculação precoce e à disfunção erétil. Também influencia testosterona e humor.', 'Peça exame de sangue ao médico. Sol de 15 a 20 minutos por dia ajuda.', '["Sol da manhã","Sardinha","Salmão","Gema de ovo","Cogumelos expostos ao sol"]'::jsonb) on conflict (id) do update set nome = excluded.nome, papel = excluded.papel, meta = excluded.meta, fontes = excluded.fontes;
insert into nutrientes (id, nome, papel, meta, fontes) values ('triptofano', 'Triptofano (serotonina)', 'A serotonina é o principal neurotransmissor que segura o reflexo de ejaculação. O triptofano é a matéria-prima para o corpo produzir serotonina.', 'Incluir fontes em todas as refeições', '["Ovos","Peru e frango","Aveia","Banana","Queijos","Sementes de girassol"]'::jsonb) on conflict (id) do update set nome = excluded.nome, papel = excluded.papel, meta = excluded.meta, fontes = excluded.fontes;
insert into nutrientes (id, nome, papel, meta, fontes) values ('omega-3', 'Ômega 3', 'Anti-inflamatório, melhora circulação e saúde do cérebro, o que ajuda humor e ansiedade.', 'Peixe gordo 2 vezes por semana', '["Sardinha","Salmão","Chia","Linhaça","Nozes"]'::jsonb) on conflict (id) do update set nome = excluded.nome, papel = excluded.papel, meta = excluded.meta, fontes = excluded.fontes;
insert into nutrientes (id, nome, papel, meta, fontes) values ('arginina', 'L-arginina e nitratos', 'Ajudam o corpo a produzir óxido nítrico, que dilata os vasos e melhora o fluxo de sangue. Ereção firme dá mais segurança e reduz a pressa.', 'Incluir diariamente', '["Beterraba","Melancia","Rúcula","Espinafre","Amendoim","Romã"]'::jsonb) on conflict (id) do update set nome = excluded.nome, papel = excluded.papel, meta = excluded.meta, fontes = excluded.fontes;
insert into nutrientes (id, nome, papel, meta, fontes) values ('complexo-b', 'Vitaminas do complexo B', 'Essenciais para o sistema nervoso e a produção de energia. B6 ajuda na produção de serotonina.', 'Dieta variada já cobre', '["Ovos","Carnes","Banana","Grão-de-bico","Batata","Folhas verdes"]'::jsonb) on conflict (id) do update set nome = excluded.nome, papel = excluded.papel, meta = excluded.meta, fontes = excluded.fontes;
insert into alimentos (id, nome, porque, imagem, nutrientes) values ('banana', 'Banana', 'Potássio, magnésio e B6. Prática para antes do treino.', '/images/alimentos/banana.webp', array['magnesio','triptofano','complexo-b']::text[]) on conflict (id) do update set nome = excluded.nome, porque = excluded.porque, imagem = excluded.imagem, nutrientes = excluded.nutrientes;
