insert into habitos (id, nome, icone, categoria, porque, como_fazer, imagem) values ('sono', 'Dormir 7 a 8 horas', 'moon', 'Corpo', 'Sono ruim derruba a testosterona e aumenta a ansiedade. Uma semana dormindo 5 horas já reduz a testosterona de forma mensurável.', '["Mesmo horário para dormir e acordar, inclusive no fim de semana.","Celular fora da cama 30 minutos antes.","Quarto escuro e fresco."]'::jsonb, '/images/habitos/sono.webp') on conflict (id) do update set nome = excluded.nome, icone = excluded.icone, categoria = excluded.categoria, porque = excluded.porque, como_fazer = excluded.como_fazer, imagem = excluded.imagem;
