insert into artigos (id, titulo, resumo, minutos, imagem, secoes) values ('o-que-e', 'O que é ejaculação precoce', 'Entenda a definição, o quanto é comum e por que tem solução.', 4, '/images/artigos/o-que-e.webp', '[{"titulo":"Você não está sozinho","texto":"A ejaculação precoce é a queixa sexual mais comum entre os homens. Pesquisas mostram que de 20% a 30% dos homens relatam o problema em algum momento da vida."},{"titulo":"A definição","texto":"Segundo a Sociedade Internacional de Medicina Sexual (ISSM), ejaculação precoce é quando a ejaculação acontece sempre ou quase sempre antes ou em cerca de 1 minuto de penetração (no tipo que existe desde a primeira relação), ou com uma redução importante para cerca de 3 minutos ou menos (no tipo adquirido), junto com a sensação de não conseguir controlar e com incômodo, frustração ou fuga da intimidade."},{"titulo":"Os tipos","texto":"Primária (ao longo da vida): existe desde as primeiras relações, com forte componente biológico e neurológico. Adquirida: surge depois de um período normal, muitas vezes ligada a ansiedade, problemas de ereção, próstata ou tireoide. Variável e subjetiva: tempo normal, mas sensação de ser rápido. Muito ligada à expectativa e à comparação com pornografia."},{"titulo":"Quanto tempo é normal?","texto":"Um estudo internacional com casais de 5 países mediu com cronômetro e encontrou um tempo mediano de cerca de 5,4 minutos de penetração. Muita gente imagina que o normal são 20 ou 30 minutos, o que não é verdade e aumenta a ansiedade."},{"titulo":"Tem solução","texto":"A combinação de treino do assoalho pélvico, técnicas comportamentais, controle da ansiedade e, quando necessário, tratamento médico traz melhora para a grande maioria dos homens."}]'::jsonb) on conflict (id) do update set titulo = excluded.titulo, resumo = excluded.resumo, minutos = excluded.minutos, imagem = excluded.imagem, secoes = excluded.secoes;
insert into artigos (id, titulo, resumo, minutos, imagem, secoes) values ('causas', 'Por que acontece', 'Cérebro, músculos, ansiedade e hábitos: o que influencia o seu tempo.', 5, '/images/artigos/causas.webp', '[{"titulo":"Serotonina","texto":"A serotonina é o freio químico da ejaculação. Homens com ejaculação precoce primária podem ter diferenças na forma como o cérebro usa a serotonina. Por isso alguns remédios que aumentam a serotonina ajudam."},{"titulo":"Ansiedade de desempenho","texto":"Medo de falhar ativa o sistema de alerta do corpo (adrenalina). Esse mesmo sistema comanda o reflexo da ejaculação. Quanto mais medo, mais rápido. Vira um ciclo."},{"titulo":"Assoalho pélvico","texto":"Músculos fracos não seguram o reflexo. Músculos tensos demais também atrapalham. O ideal é força com capacidade de relaxar."},{"titulo":"Hábitos aprendidos","texto":"Masturbação rápida desde a adolescência, por medo de ser pego, ensina o corpo a terminar depressa. Pornografia reforça esse padrão."},{"titulo":"Causas médicas","texto":"Prostatite (inflamação da próstata), hipertireoidismo, disfunção erétil e alguns remédios podem causar ou piorar. Por isso é importante uma avaliação com urologista."},{"titulo":"Sensibilidade","texto":"Alguns homens têm mais sensibilidade na glande. Técnicas de dessensibilização e anestésicos tópicos podem ajudar, sempre com orientação médica."}]'::jsonb) on conflict (id) do update set titulo = excluded.titulo, resumo = excluded.resumo, minutos = excluded.minutos, imagem = excluded.imagem, secoes = excluded.secoes;
insert into artigos (id, titulo, resumo, minutos, imagem, secoes) values ('mitos', 'Mitos e verdades', 'Separe o que funciona do que é lenda.', 4, '/images/artigos/mitos.webp', '[{"titulo":"Mito: ''Pensar em outra coisa resolve''","texto":"Distrair a mente tira o prazer e a conexão, e não ensina o corpo a controlar. O que funciona é o contrário: prestar atenção na excitação e saber regular."},{"titulo":"Mito: ''Camisinha grossa ou duas camisinhas''","texto":"Duas camisinhas aumentam o atrito e o risco de rompimento. Nunca use duas."},{"titulo":"Mito: ''É falta de homem''","texto":"É uma condição de saúde comum, com causas biológicas e psicológicas, e tem tratamento."},{"titulo":"Verdade: ''Exercício do assoalho pélvico funciona''","texto":"Estudos mostram melhora significativa após 12 semanas de reabilitação do assoalho pélvico em homens com ejaculação precoce primária."},{"titulo":"Verdade: ''Ansiedade piora''","texto":"O ciclo medo, pressa e frustração é real. Quebrar esse ciclo é parte do tratamento."},{"titulo":"Verdade: ''A segunda vez costuma durar mais''","texto":"Depois de uma ejaculação existe um período em que o reflexo fica mais lento. Alguns casais usam isso a seu favor."},{"titulo":"Mito: ''Pílulas naturais milagrosas''","texto":"Produtos vendidos na internet como ''retardante natural'' podem conter substâncias não declaradas e perigosas. Desconfie."}]'::jsonb) on conflict (id) do update set titulo = excluded.titulo, resumo = excluded.resumo, minutos = excluded.minutos, imagem = excluded.imagem, secoes = excluded.secoes;
insert into artigos (id, titulo, resumo, minutos, imagem, secoes) values ('na-hora', 'O que fazer na hora H', 'Um guia prático para usar tudo que você treinou durante a relação.', 5, '/images/artigos/na-hora.webp', '[{"titulo":"Antes","texto":"Faça 3 minutos de respiração diafragmática. Evite bebida em excesso. Lembre-se: preliminares longas são ótimas, a penetração não é a única parte do sexo."},{"titulo":"Monitore a escala","texto":"Fique atento ao seu número de 0 a 10. Quando chegar no 7, é hora de agir, não no 9."},{"titulo":"Diminua o ritmo","texto":"Movimentos mais lentos e profundos, ou movimentos circulares, estimulam menos que vai e vem rápido."},{"titulo":"Respire","texto":"Respiração lenta pela barriga. Solte o ar devagar. Ombros e mandíbula relaxados."},{"titulo":"Relaxe o assoalho","texto":"Faça um Kegel reverso: solte o assoalho pélvico. A tensão ali empurra para o ponto de não retorno."},{"titulo":"Pause sem drama","texto":"Pare, beije, troque de posição ou use as mãos e a boca na parceria. A pausa faz parte do sexo."},{"titulo":"Posições que ajudam","texto":"Parceria por cima costuma dar mais controle, porque você fica mais relaxado e ela controla o ritmo. De lado (conchinha) também ajuda por ter movimentos mais curtos."}]'::jsonb) on conflict (id) do update set titulo = excluded.titulo, resumo = excluded.resumo, minutos = excluded.minutos, imagem = excluded.imagem, secoes = excluded.secoes;
insert into artigos (id, titulo, resumo, minutos, imagem, secoes) values ('conversa', 'Como conversar com a parceria', 'Falar sobre o assunto tira um peso enorme e acelera a melhora.', 3, '/images/artigos/conversa.webp', '[{"titulo":"Escolha o momento","texto":"Fora do quarto, num momento tranquilo, sem pressa. Nunca logo depois de uma relação frustrada."},{"titulo":"Fale de você","texto":"Exemplo: ''Tenho me sentido ansioso porque termino rápido, e quero melhorar isso pra gente. Comecei um programa de exercícios.''"},{"titulo":"Peça participação","texto":"Técnicas como para e recomeça, aperto e foco sensorial funcionam melhor a dois."},{"titulo":"Lembre do prazer dela","texto":"Prazer não depende só de penetração. Mãos, boca e brinquedos tiram a pressão e fazem a relação ser boa para os dois."}]'::jsonb) on conflict (id) do update set titulo = excluded.titulo, resumo = excluded.resumo, minutos = excluded.minutos, imagem = excluded.imagem, secoes = excluded.secoes;
insert into artigos (id, titulo, resumo, minutos, imagem, secoes) values ('quando-medico', 'Quando procurar um médico', 'Sinais de alerta e quais tratamentos existem.', 4, '/images/artigos/quando-medico.webp', '[{"titulo":"Procure um urologista se","texto":"O problema começou de repente; vem junto com dificuldade de ereção; há dor ao urinar ou ejacular, sangue no sêmen ou febre; você tem sintomas de tireoide (perda de peso, tremores, coração acelerado); ou não melhorou após 3 meses de treino."},{"titulo":"Tratamentos médicos existentes","texto":"Remédios orais que agem na serotonina, como a dapoxetina e alguns antidepressivos usados fora da bula; anestésicos tópicos em spray ou creme; tratamento da disfunção erétil quando presente. Todos exigem receita e acompanhamento: não se automedique."},{"titulo":"Terapia sexual","texto":"Psicólogos e terapeutas sexuais ajudam muito, principalmente quando a ansiedade é grande ou há conflito no relacionamento."},{"titulo":"Fisioterapia pélvica","texto":"Fisioterapeutas especializados em assoalho pélvico masculino podem avaliar e montar um treino personalizado, inclusive com biofeedback."}]'::jsonb) on conflict (id) do update set titulo = excluded.titulo, resumo = excluded.resumo, minutos = excluded.minutos, imagem = excluded.imagem, secoes = excluded.secoes;
insert into artigos (id, titulo, resumo, minutos, imagem, secoes) values ('pornografia', 'Pornografia e controle', 'Como o consumo influencia sua excitação e o que fazer.', 3, '/images/artigos/pornografia.webp', '[{"titulo":"Treino ao contrário","texto":"Na maioria das vezes a pornografia vem junto com masturbação rápida, focada só no final. Isso ensina o corpo a ejacular depressa."},{"titulo":"Comparação","texto":"Cenas editadas, atores selecionados e cortes criam expectativas irreais de duração e desempenho, o que aumenta a ansiedade."},{"titulo":"O que fazer","texto":"Faça uma pausa de 30 dias. Se masturbar, faça devagar, sem tela, usando a escala de excitação como treino."}]'::jsonb) on conflict (id) do update set titulo = excluded.titulo, resumo = excluded.resumo, minutos = excluded.minutos, imagem = excluded.imagem, secoes = excluded.secoes;
insert into artigos (id, titulo, resumo, minutos, imagem, secoes) values ('masturbacao-treino', 'Masturbação como treino', 'Transforme um hábito em ferramenta de controle.', 3, '/images/artigos/masturbacao-treino.webp', '[{"titulo":"Sem pressa","texto":"Reserve 15 a 20 minutos em local tranquilo. O objetivo é ficar na zona 5 a 7, não terminar."},{"titulo":"Use lubrificante","texto":"A sensação fica mais próxima da relação, o que torna o treino mais útil."},{"titulo":"Progressão","texto":"Semana 1: mão seca e devagar. Semana 2: com lubrificante. Semana 3: com lubrificante e mais ritmo. Semana 4: pratique com a parceria."},{"titulo":"Frequência","texto":"De 3 a 4 sessões por semana são suficientes. Não precisa ser todo dia."}]'::jsonb) on conflict (id) do update set titulo = excluded.titulo, resumo = excluded.resumo, minutos = excluded.minutos, imagem = excluded.imagem, secoes = excluded.secoes;
